import unittest
from tags import normalize_tags


class Tests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(normalize_tags([" A "]), ["a"])

    def test_unicode_casefold_and_trim(self):
        self.assertEqual(normalize_tags(["\t Straße \n", "STRASSE"]), ["strasse"])

    def test_empty_list(self):
        self.assertEqual(normalize_tags([]), [])

    def test_omits_empty_tags(self):
        self.assertEqual(normalize_tags(["", " \t\n", " A ", " "]), ["a"])

    def test_deduplicates_preserving_first_order(self):
        self.assertEqual(
            normalize_tags([" B ", "a", "b", " C ", "A"]),
            ["b", "a", "c"],
        )

    def test_exactly_three_unique_tags(self):
        self.assertEqual(normalize_tags(["a", "b", "c"]), ["a", "b", "c"])

    def test_fourth_unique_tag_raises(self):
        with self.assertRaises(ValueError) as error:
            normalize_tags(["a", "b", "c", "d"])
        self.assertEqual(str(error.exception), "too many tags")

    def test_duplicates_and_blanks_do_not_consume_limit(self):
        self.assertEqual(
            normalize_tags([" A ", "a", "", "b", "B", "c", " C ", " "]),
            ["a", "b", "c"],
        )

    def test_non_string_elements_raise(self):
        for value in (None, 1, True, b"a", [], {}):
            with self.subTest(value=value):
                with self.assertRaises(TypeError) as error:
                    normalize_tags(["a", value])
                self.assertEqual(str(error.exception), "tag must be str")

    def test_input_unchanged_on_success(self):
        values = [" B ", "a", "B", ""]
        original = values.copy()
        result = normalize_tags(values)
        self.assertEqual(values, original)
        self.assertIsNot(result, values)

    def test_input_unchanged_on_error(self):
        for values, error_type in (
            ([" A ", "b", "c", "d"], ValueError),
            ([" A ", None], TypeError),
        ):
            with self.subTest(values=values):
                original = values.copy()
                with self.assertRaises(error_type):
                    normalize_tags(values)
                self.assertEqual(values, original)

