import unittest

from tags import normalize_tags


class Tests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(normalize_tags([" A "]), ["a"])

    def test_empty_and_blank_tags(self):
        for values in ([], ["", " ", "\t\n"], ["", " A ", "\t"]):
            with self.subTest(values=values):
                expected = ["a"] if " A " in values else []
                self.assertEqual(normalize_tags(values), expected)

    def test_unicode_casefold_and_trim(self):
        self.assertEqual(normalize_tags(["\t Straße\n", "STRASSE"]), ["strasse"])

    def test_deduplication_preserves_first_order(self):
        self.assertEqual(
            normalize_tags([" B ", "a", "b", " C", "A "]),
            ["b", "a", "c"],
        )

    def test_exactly_three_unique_with_extra_duplicates_and_blanks(self):
        self.assertEqual(
            normalize_tags(["a", "b", "c", " A ", "", " C "]),
            ["a", "b", "c"],
        )

    def test_four_unique_tags_raise_exact_error(self):
        with self.assertRaises(ValueError) as caught:
            normalize_tags(["a", "b", "c", "d"])
        self.assertEqual(str(caught.exception), "too many tags")

    def test_non_string_elements_raise_exact_error(self):
        for value in (None, 1, True, b"a", [], {}):
            with self.subTest(value=value):
                with self.assertRaises(TypeError) as caught:
                    normalize_tags(["a", value])
                self.assertEqual(str(caught.exception), "tag must be str")

    def test_input_unchanged_on_success(self):
        values = [" B ", "a", "B", " "]
        original = values.copy()
        result = normalize_tags(values)
        self.assertEqual(values, original)
        self.assertEqual(result, ["b", "a"])
        self.assertIsNot(result, values)

    def test_input_unchanged_on_error(self):
        for values, error in (
            ([" A ", "b", "c", "d"], ValueError),
            ([" A ", None], TypeError),
        ):
            with self.subTest(values=values):
                original = values.copy()
                with self.assertRaises(error):
                    normalize_tags(values)
                self.assertEqual(values, original)

    def test_idempotence_examples(self):
        for values in ([], [" A ", "a", ""], [" B", "Straße", " C "]):
            with self.subTest(values=values):
                normalized = normalize_tags(values)
                self.assertEqual(normalize_tags(normalized), normalized)

