from decimal import Decimal, ROUND_HALF_UP


def total(prices):
    amount = Decimal("0")
    for price in prices:
        value = Decimal(price)
        if value < 0:
            raise ValueError("negative price")
        amount += value
    return format(amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP), ".2f")

