import json
def run(argv):
    upper = len(argv) == 3 and argv[0] == "show" and argv[1] == "--upper"
    if upper:
        argv = [argv[0], argv[2]]
    if len(argv)!=2 or argv[0] not in ("show","count"):
        return 2,"","usage\n"
    command,raw=argv
    try: values=json.loads(raw)
