import unittest
from copy import deepcopy

from report import render_report


class Tests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(render_report([]), "Sin resultados — todavía")

    def test_example(self):
        self.assertEqual(
            render_report([(" Ada ", 2), ("", 0), ("A  B", 1)], 2),
            "• Ada: 2\n• (sin nombre): 0\n… y 1 más",
        )

    def test_names_and_exact_format(self):
        self.assertEqual(
            render_report([("\t ÉLoïse  李 \n", 42), (" \t\n", 0), ("A  B", 1)]),
            "• ÉLoïse  李: 42\n• (sin nombre): 0\n• A  B: 1",
        )

    def test_order_and_duplicates(self):
        self.assertEqual(
            render_report([("z", 2), ("A", 1), ("z", 2)]),
            "• z: 2\n• A: 1\n• z: 2",
        )

    def test_default_limit(self):
        self.assertEqual(
            render_report([("a", 1), ("b", 2), ("c", 3), ("d", 4)]),
            "• a: 1\n• b: 2\n• c: 3\n… y 1 más",
        )

    def test_limit_boundaries(self):
        rows = [("a", 1), ("b", 2), ("c", 3)]
        for limit, expected in [
            (1, "• a: 1\n… y 2 más"),
            (2, "• a: 1\n• b: 2\n… y 1 más"),
            (3, "• a: 1\n• b: 2\n• c: 3"),
            (4, "• a: 1\n• b: 2\n• c: 3"),
        ]:
            with self.subTest(limit=limit):
                self.assertEqual(render_report(rows, limit), expected)

    def test_invalid_limits(self):
        for limit in [True, False, 0, -1, 1.0, "2", None, [], {}]:
            for rows in [[], [("a", 1)]]:
                with self.subTest(limit=limit, rows=rows):
                    with self.assertRaises(ValueError) as caught:
                        render_report(rows, limit)
                    self.assertEqual(str(caught.exception), "límite inválido")

    def test_rows_must_be_list(self):
        for rows in [None, (), (("a", 1),), "a", {}, 1, True]:
            with self.subTest(rows=rows):
                with self.assertRaises(ValueError) as caught:
                    render_report(rows)
                self.assertEqual(str(caught.exception), "fila inválida")

    def test_invalid_rows_including_hidden(self):
        invalid_rows = [
            None, True, 1, "ab", {}, {"a": 1, "b": 2},
            (), [], ("a",), ("a", 1, 2),
            (None, 1), (1, 1), (True, 1), (b"a", 1),
            ("a", True), ("a", False), ("a", -1),
            ("a", 1.0), ("a", "1"), ("a", None),
        ]
        for row in invalid_rows:
            for rows in [[row], [("valid", 1), row]]:
                with self.subTest(row=row, hidden=len(rows) > 1):
                    before = deepcopy(rows)
                    with self.assertRaises(ValueError) as caught:
                        render_report(rows, 1)
                    self.assertEqual(str(caught.exception), "fila inválida")
                    self.assertEqual(rows, before)

    def test_no_mutation_with_mutable_pairs(self):
        rows = [[" Ada ", 2], ["", 0], ("A  B", 1)]
        before = deepcopy(rows)
        pairs = rows[:]
        for limit in [1, 3, 4]:
            with self.subTest(limit=limit):
                render_report(rows, limit)
                self.assertEqual(rows, before)
                for actual, original in zip(rows, pairs):
                    self.assertIs(actual, original)

    def test_list_pairs_and_large_nonnegative_count(self):
        self.assertEqual(
            render_report([["a", 0], ["b", 10**30]]),
            "• a: 0\n• b: 1000000000000000000000000000000",
        )

